"use client"

import * as React from "react"
import { Switch as SwitchPrimitive } from "@base-ui/react/switch"

import { cn } from "@/lib/utils"
import { useSound } from "./sound-provider"

// Clicky Switch — flat toggle, muted when off, primary when on
// Plays click sound on toggle

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Switch = React.forwardRef<
  HTMLButtonElement,
  WithClassName<SwitchPrimitive.Root.Props>
>(({ className, onCheckedChange, ...props }, ref) => {
  const { playClick } = useSound()
  return (
    <SwitchPrimitive.Root
      className={cn(
        "peer inline-flex h-5 w-9 shrink-0 cursor-pointer items-center rounded-full",
        "border border-transparent",
        "transition-all duration-base ease-out",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "data-disabled:cursor-not-allowed data-disabled:opacity-50",
        "data-unchecked:bg-muted data-unchecked:shadow-[var(--shadow-track-inset)]",
        "data-checked:bg-primary data-checked:border-[var(--primary-rim)]",
        "data-checked:shadow-[var(--shadow-tactile-control)]",
        className
      )}
      onCheckedChange={(checked, eventDetails) => {
        playClick()
        onCheckedChange?.(checked, eventDetails)
      }}
      {...props}
      ref={ref}
    >
      <SwitchPrimitive.Thumb
        className={cn(
          "pointer-events-none block h-4 w-4 rounded-full bg-background ring-0",
          "transition-transform duration-fast",
          "data-unchecked:translate-x-0.5",
          "data-checked:translate-x-[1.125rem]"
        )}
      />
    </SwitchPrimitive.Root>
  )
})
Switch.displayName = "Switch"

export { Switch }
